from __future__ import annotations

import json

from .models import PublicTrackingView

_PAGE_TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="theme-color" content="#05090c">
  <title>Jarvis location request</title>
  <style>
    :root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;--bg:#03080b;--panel:rgba(7,18,23,.92);--line:rgba(110,231,255,.22);--cyan:#79e7f7;--green:#43f5a2;--red:#ff667d;--muted:#a8bec5;--text:#effcff}*{box-sizing:border-box}body{min-height:100svh;margin:0;padding:24px;display:grid;place-items:center;color:var(--text);background:radial-gradient(circle at 50% 12%,rgba(38,160,180,.20),transparent 34%),radial-gradient(circle at 50% 100%,rgba(26,87,99,.22),transparent 45%),var(--bg)}.card{width:min(100%,560px);overflow:hidden;border:1px solid var(--line);border-radius:26px;background:var(--panel);box-shadow:0 30px 90px rgba(0,0,0,.48);backdrop-filter:blur(18px)}.hero{padding:30px 30px 20px}.brand{display:flex;align-items:center;gap:10px;color:var(--cyan);font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.pulse{width:10px;height:10px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 8px rgba(121,231,247,.08),0 0 24px rgba(121,231,247,.65)}h1{margin:24px 0 12px;font-size:clamp(31px,8vw,48px);line-height:1.05;letter-spacing:-.04em}.subtitle{margin:0;color:var(--muted);font-size:16px;line-height:1.65}.details{margin:4px 30px 0;padding:18px;display:grid;gap:12px;border:1px solid rgba(255,255,255,.07);border-radius:18px;background:rgba(255,255,255,.025)}.row{display:flex;justify-content:space-between;gap:16px;color:var(--muted);font-size:14px}.row strong{color:var(--text);font-weight:650;text-align:right}.status-panel{margin:18px 30px 0;padding:15px 16px;display:flex;align-items:center;gap:12px;border-radius:15px;background:rgba(121,231,247,.07);color:var(--cyan);font-size:14px;line-height:1.45}.status-dot{flex:0 0 auto;width:9px;height:9px;border-radius:50%;background:currentColor;box-shadow:0 0 14px currentColor}.metrics{margin:12px 30px 0;display:none;grid-template-columns:1fr 1fr;gap:10px}.metric{padding:13px 15px;border-radius:14px;background:rgba(255,255,255,.035);color:var(--muted);font-size:12px}.metric strong{display:block;margin-top:5px;color:var(--text);font-size:15px}.actions{padding:22px 30px 30px;display:grid;grid-template-columns:1fr 1fr;gap:12px}button{min-height:54px;padding:14px 18px;border:0;border-radius:15px;font:inherit;font-weight:800;cursor:pointer}button:disabled{opacity:.48;cursor:not-allowed}.allow{color:#02120c;background:linear-gradient(135deg,var(--green),#79f5e2)}.deny{color:#ffdbe2;background:rgba(255,102,125,.10);border:1px solid rgba(255,102,125,.25)}.stop{display:none;grid-column:1/-1;color:white;background:linear-gradient(135deg,#f44e68,#bd2949)}.notice{margin:0 30px 28px;color:#81989f;font-size:12px;line-height:1.55;text-align:center}@media(max-width:520px){body{padding:14px}.hero{padding:25px 22px 16px}.details,.status-panel,.metrics{margin-left:22px;margin-right:22px}.actions{padding:18px 22px 24px;grid-template-columns:1fr}.stop{grid-column:auto}.notice{margin-left:22px;margin-right:22px}}
  </style>
</head>
<body>
  <main class="card">
    <section class="hero"><div class="brand"><span class="pulse"></span> Jarvis secure location request</div><h1><span id="requesterName">Abhi</span> wants your live location.</h1><p class="subtitle">Allow Jarvis to share your GPS location for a limited time. Nothing is sent until you choose Allow, and you can stop at any moment.</p></section>
    <section class="details"><div class="row"><span>Sharing with</span><strong id="requesterDetail">Abhi</strong></div><div class="row"><span>Maximum duration</span><strong id="duration">15 minutes</strong></div><div class="row"><span>Time remaining</span><strong id="remaining">--:--</strong></div></section>
    <div class="status-panel" id="statusPanel"><span class="status-dot"></span><span id="statusText">Waiting for your decision.</span></div>
    <section class="metrics" id="metrics"><div class="metric">GPS accuracy<strong id="accuracy">Waiting…</strong></div><div class="metric">Last sent<strong id="lastSent">Not yet</strong></div></section>
    <section class="actions"><button class="allow" id="allowButton">Allow Jarvis to track you</button><button class="deny" id="denyButton">Deny</button><button class="stop" id="stopButton">Stop sharing now</button></section>
    <p class="notice">Keep this page open for reliable updates. Mobile browsers may pause GPS sharing when the page is hidden or the phone is locked.</p>
  </main>
  <script>
    window.__TRACKING__=__PAGE_DATA__;
    (()=>{const c=window.__TRACKING__,$=id=>document.getElementById(id),requesterName=$("requesterName"),requesterDetail=$("requesterDetail"),duration=$("duration"),remaining=$("remaining"),statusPanel=$("statusPanel"),statusText=$("statusText"),metrics=$("metrics"),accuracy=$("accuracy"),lastSent=$("lastSent"),allowButton=$("allowButton"),denyButton=$("denyButton"),stopButton=$("stopButton");let socket=null,watchId=null,consentRecorded=false,stopped=false,pendingPoint=null,lastSentAt=0,lastLatitude=null,lastLongitude=null,reconnectTimer=null;requesterName.textContent=c.requesterName;requesterDetail.textContent=c.requesterName;duration.textContent=`${c.durationMinutes} minutes`;const setStatus=(m,t="cyan")=>{statusText.textContent=m;statusPanel.style.color=({cyan:"#79e7f7",green:"#43f5a2",red:"#ff667d",muted:"#a8bec5"})[t]||"#79e7f7"},setActiveUi=()=>{allowButton.style.display="none";denyButton.style.display="none";stopButton.style.display="block";metrics.style.display="grid"},setEndedUi=(m,t="muted")=>{stopped=true;if(watchId!==null)navigator.geolocation.clearWatch(watchId);if(socket)socket.close(1000,"sharing-ended");clearTimeout(reconnectTimer);allowButton.style.display="none";denyButton.style.display="none";stopButton.style.display="none";setStatus(m,t)},updateTimer=()=>{const ms=new Date(c.expiresAt).getTime()-Date.now();if(ms<=0){remaining.textContent="Expired";setEndedUi("This location request has expired.");return}const total=Math.floor(ms/1000),m=Math.floor(total/60),s=String(total%60).padStart(2,"0");remaining.textContent=`${m}:${s}`};updateTimer();setInterval(updateTimer,1000);const postJson=async(path,body=null)=>{const r=await fetch(path,{method:"POST",headers:{"Content-Type":"application/json"},body:body?JSON.stringify(body):undefined,cache:"no-store"});if(!r.ok)throw new Error(await r.text()||`Request failed (${r.status})`);return r.json()},websocketUrl=()=>`${location.protocol==="https:"?"wss:":"ws:"}//${location.host}/ws/tracking/share/${encodeURIComponent(c.publicToken)}`,connectSocket=()=>{if(stopped||socket?.readyState===WebSocket.OPEN||socket?.readyState===WebSocket.CONNECTING)return;socket=new WebSocket(websocketUrl());socket.addEventListener("open",()=>{setStatus("GPS connected. Waiting for a location fix…","green");if(pendingPoint&&consentRecorded){socket.send(JSON.stringify(pendingPoint));pendingPoint=null}});socket.addEventListener("message",event=>{try{const m=JSON.parse(event.data);if(m.type==="location_ack"){lastSent.textContent="Just now";setStatus("Live location is being shared with Abhi.","green")}}catch(_){}});socket.addEventListener("close",event=>{socket=null;if(!stopped&&event.code!==4403&&event.code!==4408){setStatus("Connection interrupted. Reconnecting…");reconnectTimer=setTimeout(connectSocket,2000)}});socket.addEventListener("error",()=>setStatus("Unable to reach Jarvis. Retrying…","red"))},distanceMetres=(a,b,x,y)=>{const r=6371000,toRad=v=>v*Math.PI/180,dLat=toRad(x-a),dLon=toRad(y-b),h=Math.sin(dLat/2)**2+Math.cos(toRad(a))*Math.cos(toRad(x))*Math.sin(dLon/2)**2;return r*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))},shouldSend=p=>{const now=Date.now();if(lastSentAt===0||now-lastSentAt>=15000)return true;if(now-lastSentAt<3000)return false;if(lastLatitude===null||lastLongitude===null)return true;return distanceMetres(lastLatitude,lastLongitude,p.coords.latitude,p.coords.longitude)>=5},handlePosition=p=>{accuracy.textContent=`±${Math.round(p.coords.accuracy)} metres`;if(!shouldSend(p))return;const point={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,heading:Number.isFinite(p.coords.heading)?p.coords.heading:null,speed:Number.isFinite(p.coords.speed)?p.coords.speed:null,timestamp:Math.round(p.timestamp)};lastSentAt=Date.now();lastLatitude=point.latitude;lastLongitude=point.longitude;if(consentRecorded&&socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify(point));else pendingPoint=point},handleLocationError=async e=>{if(e.code===1){try{await postJson(`/api/tracking/public/${encodeURIComponent(c.publicToken)}/decision`,{decision:"DENY"})}catch(_){}setEndedUi("Location permission was denied. Nothing was shared.","red");return}setStatus(`GPS error: ${e.message}`,"red")};allowButton.addEventListener("click",async()=>{if(!navigator.geolocation){setEndedUi("This browser does not support GPS sharing.","red");return}allowButton.disabled=true;denyButton.disabled=true;setActiveUi();setStatus("Requesting your browser's location permission…");watchId=navigator.geolocation.watchPosition(handlePosition,handleLocationError,{enableHighAccuracy:true,maximumAge:3000,timeout:15000});connectSocket();try{await postJson(`/api/tracking/public/${encodeURIComponent(c.publicToken)}/decision`,{decision:"ALLOW"});consentRecorded=true;setStatus("Permission granted. Waiting for a GPS fix…","green");if(pendingPoint&&socket?.readyState===WebSocket.OPEN){socket.send(JSON.stringify(pendingPoint));pendingPoint=null}}catch(_){setEndedUi("Jarvis could not activate this request. Please reopen the link.","red")}});denyButton.addEventListener("click",async()=>{allowButton.disabled=true;denyButton.disabled=true;try{await postJson(`/api/tracking/public/${encodeURIComponent(c.publicToken)}/decision`,{decision:"DENY"});setEndedUi("Request denied. No location was shared.")}catch(_){setStatus("Could not submit your decision. Please try again.","red");allowButton.disabled=false;denyButton.disabled=false}});stopButton.addEventListener("click",async()=>{stopButton.disabled=true;try{await postJson(`/api/tracking/public/${encodeURIComponent(c.publicToken)}/stop`)}finally{setEndedUi("Location sharing stopped.")}});document.addEventListener("visibilitychange",()=>{if(document.hidden&&!stopped&&watchId!==null)setStatus("Keep this page visible for reliable GPS updates.")});if(["DENIED","ENDED","EXPIRED"].includes(c.status))setEndedUi(`This request is ${c.status.toLowerCase()}.`)})();
  </script>
</body>
</html>'''


def render_consent_page(
    *,
    public_token: str,
    session: PublicTrackingView,
) -> str:
    payload = {
        "publicToken": public_token,
        "requesterName": session.requester_name,
        "targetName": session.target_name,
        "durationMinutes": session.duration_minutes,
        "status": session.status.value,
        "expiresAt": session.expires_at.isoformat(),
    }
    data = json.dumps(
        payload,
        ensure_ascii=False,
        separators=(",", ":"),
    ).replace("</", "<\\/")
    return _PAGE_TEMPLATE.replace("__PAGE_DATA__", data)